import 'package:flutter_test/flutter_test.dart';import 'package:finaro/domain/forecast_engine.dart';import 'package:finaro/domain/models/models.dart';void main(){test('forecast is deterministic',(){final p=FinancialProfile(openingBalanceRials:10000000);final x=Income(id:'1',title:'حقوق',amountRials:2000000,frequency:'ماهانه',start:'2026-01-01',payDay:13);final rows=ForecastEngine.build(profile:p,incomes:[x],expenses:[],liabilities:[],days:60);expect(rows.length,60);expect(rows.every((e)=>e.balanceRials>=10000000),true);});}
